// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as handler } from "../.open-next/worker.js";
import { checkDemoAccess } from "../src/lib/demo/access-gate";
import { type RateLimiter, rateLimitApi } from "../src/lib/rate-limit/api-rate-limit";

interface Env {
  API_RATE_LIMITER: RateLimiter;
  /** Worker secret: comma-separated `recipient:key` pairs. */
  DEMO_ACCESS_KEYS?: string;
}

/** Lets only visitors with an access key in, then applies the per-IP /api/* limit, before OpenNext runs. */
export default {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    const denied = checkDemoAccess(request, env.DEMO_ACCESS_KEYS);
    if (denied) return denied;
    const limited = await rateLimitApi(request, env.API_RATE_LIMITER);
    return limited ?? handler.fetch(request, env, ctx);
  },
};
